  --color-accent-foreground: var(--on-surface-default, #e6e8f0);
  --color-muted: var(--surface-container, #2c2e35);
  --color-muted-foreground: var(--on-surface-de-emphasis, #adafb8);
  --color-foreground: var(--on-surface-default, #e6e8f0);
  --color-disabled: var(--surface-container, #2c2e35);
  --color-disabled-foreground: var(--disabled-foreground, #797c90);
}

input[type="date"]::-webkit-calendar-picker-indicator {
  cursor: pointer;
  opacity: .6;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light) input[type="date"]::-webkit-calendar-picker-indicator {
    filter: invert();
    opacity: .7;
  }
}

.dark input[type="date"]::-webkit-calendar-picker-indicator {
  filter: invert();
  opacity: .7;
}

